def solve(n, k):
    if n < k:
        return "NO"

    # Start with the maximum possible value for the first day
    a = [1] * k
    total = k

    # Adjust the values to sum up to n
    for i in range(k):
        while total + (1 << (k - i - 1)) - 1 <= n:
            total += 1 << (k - i - 1)
            a[i] += 1 << (k - i - 1)

    if total == n:
        return "YES\n" + " ".join(map(str, a))
    else:
        return "NO"

